with unpacked as (select id, context, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').duration as duration_sec, context['version'] as version from app_logs) select id, version, last_value(duration_sec) ignore nulls over (order by duration_sec, id rows between unbounded preceding and current row) last_known_duration_sec, last_value(duration_sec, true) over (order by duration_sec, id rows between unbounded preceding and current row) last_known_duration_sec_2, percent_rank() over (order by duration_sec nulls first) duration_sec_percent_rank from unpacked
